// Pixel flatline detector - tune here.
// Defaults suit a pixel that should fire at least daily; raise for low-traffic pixels.
return [{ json: {
  FLATLINE_HOURS: 24,  // alert if a pixel has not fired for this many hours
  WARN_HOURS: 12,      // watch (not yet an alert) if a pixel has been quiet this long
  IGNORE_NEVER_FIRED: true, // skip pixels that have never fired (usually test/unused)
} }];

// Flag pixels that have gone quiet: no events for longer than the flatline threshold.
const cfg = $('Set config: flatline thresholds').first().json;
const now = Date.now();
const rows = ($json.data || []).map((p) => {
  const last = p.last_fired_time ? new Date(p.last_fired_time).getTime() : null;
  const hours = last ? +(((now - last) / 3600000)).toFixed(1) : null;
  let status = 'ok';
  if (hours == null) status = 'never_fired';
  else if (hours >= cfg.FLATLINE_HOURS) status = 'flatline';
  else if (hours >= cfg.WARN_HOURS) status = 'warn';
  return { id: p.id, name: p.name || p.id, last_fired_time: p.last_fired_time || null, hours_quiet: hours, status };
});
const alerts = rows.filter((r) => r.status === 'flatline' || (r.status === 'never_fired' && !cfg.IGNORE_NEVER_FIRED));
const watch = rows.filter((r) => r.status === 'warn');
rows.sort((a, b) => (b.hours_quiet == null ? 1e9 : b.hours_quiet) - (a.hours_quiet == null ? 1e9 : a.hours_quiet));
return [{ json: {
  checked: rows.length,
  flatline_count: alerts.length,
  watch_count: watch.length,
  flatline_hours: cfg.FLATLINE_HOURS,
  pixels: rows,
  alerts,
} }];

// Ask Claude to diagnose the most likely cause of each flatlined pixel.
const d = $json;
const top = (d.alerts || []).slice(0, 20); // cap so the JSON reply never truncates
const system = 'You are a Meta measurement engineer. You are given Meta pixels and how long each has been silent (no events received). For each flatlined or never-fired pixel, give the single most likely cause (tag removed by a site deploy, consent/CMP blocking, GTM misfire, test-only pixel, or genuinely low traffic) and one concrete first check. Be terse. Return ONLY valid JSON, no prose, no markdown fences.';
const user = 'Flatline threshold: ' + d.flatline_hours + 'h. Checked ' + d.checked + ' pixels, ' + d.flatline_count + ' flatlined.\n\nPixels:\n' + JSON.stringify(top) + '\n\nReturn JSON exactly: {"summary":"one sentence","diagnoses":[{"pixel":"","hours_quiet":0,"likely_cause":"","first_check":""}]}';
const body = { model: 'claude-haiku-4-5', max_tokens: 3000, system, messages: [{ role: 'user', content: user }] };
return [{ json: { body, _ctx: d } }];

// Print a readable pixel flatline report. Swap this node for Slack or email to get paged.
const ctx = $('Build AI diagnosis prompt').first().json._ctx || {};
function aiJson(fallback) {
  const t = ($json.content && $json.content[0] && $json.content[0].text) || '';
  let s = String(t).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const m = s.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return fallback;
}
const ai = aiJson({ summary: 'AI response could not be parsed.', diagnoses: [] });

const lines = [];
lines.push('META PIXEL FLATLINE REPORT');
lines.push('Checked: ' + (ctx.checked || 0) + ' | Flatlined: ' + (ctx.flatline_count || 0) + ' | Watch: ' + (ctx.watch_count || 0));
lines.push('Threshold: no events for ' + (ctx.flatline_hours || 0) + 'h');
lines.push('');
lines.push(ai.summary || '');
lines.push('');
for (const g of (ai.diagnoses || [])) {
  lines.push('- ' + g.pixel + '  (quiet ' + g.hours_quiet + 'h)');
  if (g.likely_cause) lines.push('    cause: ' + g.likely_cause);
  if (g.first_check) lines.push('    check: ' + g.first_check);
}
return [{ json: { report: lines.join('\n'), pixels: ctx.pixels || [], ai } }];
